final Map<String, MhnTest> kMasterTestsByCode = {
  for (final t in kMasterTests) if (t.code.isNotEmpty) t.code.toUpperCase(): t,
};

final Map<String, MhnTest> kMasterTestsById = {
  for (final t in kMasterTests) t.id.toLowerCase(): t,
};

MhnTest? findMasterTest(String? code, [String? id, String? name]) {
  if (code != null && code.isNotEmpty) {
    final t = kMasterTestsByCode[code.trim().toUpperCase()];
    if (t != null) return t;
  }
  if (id != null && id.isNotEmpty) {
    final t = kMasterTestsById[id.trim().toLowerCase()];
    if (t != null) return t;
  }
  if (name != null && name.isNotEmpty) {
    final upper = name.trim().toUpperCase();
    for (final t in kMasterTests) {
      if (t.name.toUpperCase() == upper) return t;
    }
  }
  return null;
}
